import{_ as n,o as i,c as e,a2 as a}from"./chunks/framework.BfI5QxtK.js";const h=JSON.parse('{"title":"Config API","description":"","frontmatter":{},"headers":[],"relativePath":"config.md","filePath":"config.md"}'),t={name:"config.md"};function s(c,o,r,l,d,g){return i(),e("div",null,[...o[0]||(o[0]=[a(`<h1 id="config-api" tabindex="-1">Config API <a class="header-anchor" href="#config-api" aria-label="Permalink to &quot;Config API&quot;">​</a></h1><p>Use <a href="/gnoblin/config/configure"><code>gnoblin.configure</code></a> for settings, named shortcuts and autostart commands. The reference pages list the supported fields and defaults.</p><h2 id="functions" tabindex="-1">Functions <a class="header-anchor" href="#functions" aria-label="Permalink to &quot;Functions&quot;">​</a></h2><ul><li><a href="/gnoblin/config/configure"><code>gnoblin.configure</code></a> — set compositor, shell, input and window-management options.</li><li><a href="/gnoblin/config/window_rule"><code>gnoblin.window_rule</code></a> — add a window or layer-surface rule.</li><li><a href="/gnoblin/config/permission_rule"><code>gnoblin.permission_rule</code></a> — add a portal permission rule.</li><li><a href="/gnoblin/config/load"><code>gnoblin.load</code></a> — load another Lua config file.</li><li><a href="/gnoblin/config/snapshot"><code>gnoblin.snapshot</code></a> — inspect a copy of the current config.</li><li><a href="/gnoblin/config/array"><code>gnoblin.array</code></a> — mark a Lua table as a list.</li></ul><p>The named views <a href="/gnoblin/config/configure/shortcuts"><code>gnoblin.configure.shortcuts</code></a> and <a href="/gnoblin/config/configure/autostart"><code>gnoblin.configure.autostart</code></a> read or update entries by name. See the <a href="/gnoblin/guides/shortcuts">shortcuts</a> and <a href="/gnoblin/guides/autostart">autostart</a> guides. Lua&#39;s <code>require</code> loader is covered under <a href="/gnoblin/config/load"><code>gnoblin.load</code></a>.</p><h2 id="compatibility-functions" tabindex="-1">Compatibility functions <a class="header-anchor" href="#compatibility-functions" aria-label="Permalink to &quot;Compatibility functions&quot;">​</a></h2><p>Older configs can still use <a href="/gnoblin/config/shortcut"><code>gnoblin.shortcut</code></a>, <a href="/gnoblin/config/autostart"><code>gnoblin.autostart</code></a>, <a href="/gnoblin/config/remove_shortcut"><code>gnoblin.remove_shortcut</code></a>, <a href="/gnoblin/config/remove_autostart"><code>gnoblin.remove_autostart</code></a> and <a href="/gnoblin/config/set"><code>gnoblin.set</code></a>. New configs can edit named shortcuts and autostart entries through <code>gnoblin.configure</code>.</p><h2 id="first-config" tabindex="-1">First config <a class="header-anchor" href="#first-config" aria-label="Permalink to &quot;First config&quot;">​</a></h2><p>On first login, <code>gnoblin-session</code> copies the packaged reference config to <code>~/.config/gnoblin/init.lua</code> when no Lua or legacy config exists. It does not replace an existing config. Edit that file to configure Gnoblin.</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">gnoblinctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> config</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> path</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">gnoblinctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> config</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> reload</span></span></code></pre></div><p>See <a href="/gnoblin/recipes">configuration recipes</a> for complete examples and the <a href="/gnoblin/guides/window_rules">guides</a> for task-based instructions.</p>`,11)])])}const u=n(t,[["render",s]]);export{h as __pageData,u as default};
